function toast(m){document.querySelectorAll('#toast').forEach(e=>e.remove());const e=document.createElement('div');e.id='toast';e.setAttribute('role','status');e.textContent=m;document.body.appendChild(e);setTimeout(()=>e.remove(),3200)}
const errMsg=e=>{const m=e&&(e.message||e.error_description);if(m&&/species_check/.test(m))return t('dbSpecies');return m&&!/fetch|network/i.test(m)?m:t('err')};
function fmtDate(d){try{return new Date(d+'T12:00:00').toLocaleDateString(S.lang==='en'?'en-GB':'sv-SE',{day:'numeric',month:'long'})}catch(e){return d||''}}
const speciesName=s=>t(s);
const mineP=p=>!!p.mineFlag||(S.user&&p.owner===S.user.name);
function langSw(){return `<div class="lang" role="group" aria-label="${esc(t('language'))}"><button data-act="lang" data-v="sv" class="${S.lang==='sv'?'on':''}">SV</button><button data-act="lang" data-v="en" class="${S.lang==='en'?'on':''}">EN</button></div>`}
function topbar(title,sub){return `<div class="top"><div class="brand"><span class="logo">${sz(paw,22).replace('.45','1')}</span>${t('appname')}</div>${langSw()}</div>${title?`<div class="pad"><h1>${esc(title)}</h1>${sub?`<p class="sub">${esc(sub)}</p>`:''}</div>`:''}`}
function head(title,sub,back){return `<div class="top"><a class="back" href="${back}" aria-label="${esc(t('back'))}">${ic.back}</a>${langSw()}</div><div class="pad"><h1>${esc(title)}</h1>${sub?`<p class="sub">${esc(sub)}</p>`:''}</div>`}
function nav(r){const n=S.unread;const a=(h,k,i,on)=>`<a href="#/${h}" class="${on?'on':''}">${i}${t(k)}</a>`;
$('#navwrap').innerHTML=`<nav aria-label="Navigation">${a('','navLost',ic.list,r==='')}${a('mine','navMine',sz(paw,26).replace('fill="#3A2A1E" fill-opacity=".45"','fill="currentColor"'),r==='mine'||r==='addpet'||r==='edit')}<a href="#/found" class="cam ${r==='found'||r==='results'?'on':''}"><span>${ic.cam}</span>${t('navFound')}</a><a href="#/messages" class="${r==='messages'||r==='chat'?'on':''}">${ic.msg}${n?`<i class="badge">${n}</i>`:''}${t('navMsg')}</a>${a('profile','navProfile',ic.user,r==='profile'||r==='login'||r==='reset')}</nav>`}
const photoOf=p=>p.imgs&&p.imgs.length?`<img src="${esc(p.imgs[0])}" alt="${esc(p.name)}">`:paw;
const tagOf=p=>`<span class="tag ${p.status==='lost'?'t-lost':p.status==='found'?'t-found':'t-reg'}">${t(p.status==='found'?'foundSt':p.status==='lost'?'lost':'registered')}</span>`;
function petCard(p,extra){extra=extra||{};return `<a class="card ${extra.hl?'hl':''}" href="#/pet/${p.id}"><div class="ph">${photoOf(p)}</div><div class="grow"><div style="display:flex;justify-content:space-between;gap:8px;align-items:center"><span class="name">${esc(p.name)}</span>${extra.tag||tagOf(p)}</div><span class="muted">${esc(speciesName(p.species))} · ${esc(p.color)}</span><span style="font-size:14px;font-weight:700">${esc(p.place)}, ${esc(p.city)}</span><span class="muted">${esc(fmtDate(p.date))}</span>${extra.body||''}</div></a>`}
/* ---------- vyer (hämtar data från databasen) ---------- */
function breedFilter(){const sp=tmp.sp;const lbl=x=>x==='Blandras'?t('mixedBreed'):breedDisp(x);
if(!BREEDS(sp).length)return `<select id="qb" disabled aria-label="${esc(t('fBreed'))}"><option>${esc(t(sp==='all'?'speciesFirst':'noBreedsOther'))}</option></select>`;
const sp0=['Huskatt','Blandras','Okänd'].filter(x=>!(x==='Huskatt'&&sp!=='cat')&&!(x==='Blandras'&&FREE(sp)));const list=BREEDS(sp).slice().sort((a,b)=>a.localeCompare(b,S.lang==='en'?'en':'sv'));
return `<select id="qb" aria-label="${esc(t('fBreed'))}"><option value="">${esc(t('allBreeds'))}</option>${sp0.concat(list).map(x=>`<option value="${esc(x)}" ${tmp.qb===x?'selected':''}>${esc(lbl(x))}</option>`).join('')}</select>`}
function nFilters(){return (tmp.qb?1:0)+(tmp.qc?1:0)+(tmp.qp?1:0)+(tmp.qs?1:0)+(tmp.qd?1:0)}
async function vList(){const n=nFilters();const sx=[['','anySex'],['f','female'],['m','male']];const dd=[['','anyTime'],['7','last7'],['30','last30'],['90','last90']];
return `${topbar(t('lostTitle'),t('lostSub'))}<div class="pad"><div class="field" style="margin:0 0 12px"><label for="bc">${t('showing')}</label>${countrySel('bc',S.country)}</div><div class="row" style="margin-bottom:12px">${['all','cat','dog','bird','rabbit','rodent','reptile','other'].map(s=>`<button class="chip ${tmp.sp===s?'on':''}" data-act="sp" data-v="${s}">${t(s)}</button>`).join('')}</div>
<button type="button" class="chip filterbtn ${tmp.fopen||n?'on':''}" data-act="togFilters" aria-expanded="${tmp.fopen?'true':'false'}"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#3A2A1E" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 5h18l-7 8.5V20l-4-2v-4.5z"/></svg> <span id="fcnt">${t('filters')}${n?` (${n})`:''}</span></button>
<div id="fpanel" class="fpanel" ${tmp.fopen?'':'hidden'}><div class="lbl" style="margin-bottom:6px">${t('fBreed')}</div>${breedFilter()}
<div class="lbl" style="margin:12px 0 6px">${t('fColor')}</div><select id="qc" aria-label="${esc(t('fColor'))}"><option value="">${esc(t('allColors'))}</option>${COLORS.map(x=>`<option value="${esc(x[0])}" ${tmp.qc===x[0]?'selected':''}>${esc(x[S.lang==='en'?1:0])}</option>`).join('')}</select>
<div class="lbl" style="margin:12px 0 6px">${t('fSex')}</div><div class="row">${sx.map(x=>`<button class="chip ${(tmp.qs||'')===x[0]?'on':''}" data-act="setSex" data-v="${x[0]}">${t(x[1])}</button>`).join('')}</div>
<div class="lbl" style="margin:12px 0 6px">${t('fSince')}</div><select id="qd" aria-label="${esc(t('fSince'))}">${dd.map(x=>`<option value="${x[0]}" ${(tmp.qd||'')===x[0]?'selected':''}>${t(x[1])}</option>`).join('')}</select>
<div class="lbl" style="margin:12px 0 6px">${t('locLabel')}</div><div class="locrow"><input type="text" id="qp" value="${esc(tmp.qp)}" placeholder="${esc(t('filterPlacePh'))}" aria-label="${esc(t('locLabel'))}" autocomplete="off"><button type="button" class="locbtn" data-act="locFilter" aria-label="${esc(t('useLoc'))}" title="${esc(t('useLoc'))}"><svg width="32" height="32" viewBox="0 0 24 24" aria-hidden="true"><path fill="#3A2A1E" d="M12 1.2c-4.3 0-7.8 3.4-7.8 7.7 0 5.5 6.4 12.600 7.200 13.400.3.3.9.3 1.200 0 .8-.8 7.200-7.900 7.200-13.400 0-4.300-3.500-7.700-7.800-7.700z"/><g transform="translate(7.1 4.2) scale(.155)" fill="#FFD770"><ellipse cx="14" cy="29" rx="5.5" ry="7.5" transform="rotate(-22 14 29)"/><ellipse cx="25" cy="17" rx="6" ry="8.5" transform="rotate(-8 25 17)"/><ellipse cx="39" cy="17" rx="6" ry="8.5" transform="rotate(8 39 17)"/><ellipse cx="50" cy="29" rx="5.5" ry="7.5" transform="rotate(22 50 29)"/><path d="M32 29c-8 0-16.500 9-16.500 17.500 0 6 5 8.500 9.500 7.500 3-.7 4.500-2 7-2s4 1.300 7 2c4.500 1 9.500-1.500 9.500-7.500C48.500 38 40 29 32 29z"/></g></svg></button></div><div id="sug" class="sug"></div>
${n?`<button type="button" class="chip" style="margin-top:12px" data-act="clearFilters">${t('clearFilters')}</button>`:''}</div>
<div id="list" style="margin-top:14px"><div class="hint">${t('loading')}</div></div></div>`}
let listTok=0;
async function fillList(){const tok=++listTok;const fc=$('#fcnt');if(fc)fc.textContent=t('filters')+(nFilters()?` (${nFilters()})`:'');const el=$('#list');if(!el)return;try{const items=await DB.searchLost({breed:tmp.qb.trim(),color:tmp.qc.trim(),place:tmp.qp.trim()},tmp.sp,S.country);if(tok!==listTok||!$('#list'))return;let it=items;if(tmp.qs)it=it.filter(p=>p.sex===tmp.qs);if(tmp.qd){const lim=new Date();lim.setDate(lim.getDate()-(+tmp.qd));const ls=lim.getFullYear()+'-'+String(lim.getMonth()+1).padStart(2,'0')+'-'+String(lim.getDate()).padStart(2,'0');it=it.filter(p=>String(p.date||'')>=ls)}$('#list').innerHTML=it.length?it.map(p=>petCard(p)).join(''):(nFilters()||tmp.sp!=='all'?emptyCard(t('noLost2'),t('noLostSub')):emptyCard(t('noRegistered'),t('noRegisteredSub')))}catch(e){if(tok===listTok&&$('#list'))$('#list').innerHTML=`<div class="info warn">${esc(errMsg(e))}</div>`}}
async function vPet(id){let p=await DB.getLost(id);if(!p&&S.user)p=await DB.myPet(id);if(!p)return head(t('notFound'),'','#/');
const ph=p.imgs||[];const i=Math.min(tmp.photoIdx,Math.max(ph.length-1,0));const own=mineP(p);
return `<div class="hero"><a class="back" href="#/" aria-label="${esc(t('back'))}">${ic.back}</a>${ph.length?`<img src="${esc(ph[i])}" alt="${esc(p.name)}">`:sz(paw,84)}${i>0?`<button class="arr l" data-act="phPrev" aria-label="${esc(t('prevPhoto'))}">‹</button>`:''}${i<ph.length-1?`<button class="arr r" data-act="phNext" aria-label="${esc(t('nextPhoto'))}">›</button>`:''}${ph.length>1?`<div class="dots">${ph.map((_,k)=>`<i class="${k===i?'on':''}"></i>`).join('')}</div>`:''}</div>
<div class="pad"><div style="display:flex;justify-content:space-between;align-items:center"><h1>${esc(p.name)}</h1>${tagOf(p)}</div>
<div class="grid3" style="margin-top:14px"><div class="cell"><small>${t('species')}</small><b>${esc(speciesName(p.species))}</b></div><div class="cell"><small>${t('sex')}</small><b>${esc(p.sex==='f'?t('female'):p.sex==='m'?t('male'):t('unknown'))}</b></div><div class="cell"><small>${t('age')}</small><b>${p.age!=null&&p.age!==''?esc(p.age)+' '+t('years'):'–'}</b></div><div class="cell" style="grid-column:span 3"><small>${t('colorBreed')}</small><b>${esc(p.color)}${p.breed?' · '+esc(breedDisp(p.breed)):''}</b></div></div>
${p.marks?`<div class="field"><div class="lbl" style="color:var(--m);font-size:13px">${t('marks')}</div><div style="font-weight:600;line-height:1.4">${esc(p.marks)}</div></div>`:''}
${p.status==='lost'?`<div class="card"><div class="grow"><b>${t('lastSeen')}: ${esc(p.place)}, ${esc(p.city)}</b><span class="muted">${esc(fmtDate(p.date))}${p.circ?' · '+esc(p.circ):''}</span></div></div>`:''}
${own?'':`<div class="info"><b>${t('owner')}: ${esc(p.owner)}.</b> ${t('ownerNote')}</div>`}
<div style="margin-top:16px">${own?`<a class="btn sec" href="#/mine">${t('manage')}</a>`:p.status==='lost'?`<a class="btn" href="#/contact/${p.id}">${t('contactOwner')}</a>`:''}</div></div>`}
async function vContact(id){const p=await DB.getLost(id);if(!p)return head(t('notFound'),'','#/');return `${head(t('contactTitle'),'',`#/pet/${id}`)}<div class="pad"><div class="card" style="margin-top:0"><div class="ph" style="width:56px;height:56px">${photoOf(p)}</div><div class="grow"><span class="name">${esc(p.name)}</span><span class="muted">${esc(speciesName(p.species))} · ${esc(p.place)}, ${esc(p.city)}</span></div></div>
<div class="field"><label for="intro">${t('introLbl')}</label><textarea id="intro" rows="6" maxlength="2000" placeholder="${esc(t('introPh'))}"></textarea><div class="hint" style="display:flex;justify-content:space-between"><span>${t('needOne')}</span><span id="cnt">0 / 2000</span></div></div>
<div class="info"><b>${t('howTitle')}</b><br>1. ${t('how1')}<br>2. ${t('how2')}<br>3. ${t('how3')}</div>
<div style="margin-top:16px"><button class="btn" data-act="sendReq" data-v="${id}">${t('sendReq')}</button></div></div>`}
async function vFound(){const ph=tmp.foundPhotos;const f=tmp.find||{species:'',place:'',desc:''};
return `${head(t('foundTitle'),t('foundSub'),'#/')}<div class="pad"><div class="lbl" style="margin-top:6px">${t('s1')}</div><div class="thumbs">
<label class="add"><input type="file" accept="image/*" capture="environment" hidden data-file="found">${sz(ic.cam,26)}${t('takePhoto')}</label>
${ph.map((s,i)=>`<div class="thumb"><img src="${esc(s.url)}" alt=""><button data-act="rmFound" data-v="${i}" aria-label="${esc(t('removePhoto'))}">×</button></div>`).join('')}
<label class="add" style="background:#fff;border:1.5px solid var(--db)"><input type="file" accept="image/*" multiple hidden data-file="found"><span style="font-size:24px">+</span>${t('pickPhotos')}</label></div>
<div class="lbl" style="margin-top:16px">${t('s2')}</div><div class="row">${['cat','dog','bird','rabbit','rodent','reptile','other'].map(s=>`<button class="chip ${f.species===s?'on':''}" data-act="fsp" data-v="${s}">${t(s)}</button>`).join('')}</div>
<div class="lbl" style="margin-top:16px">${t('s3')}</div><div class="locrow"><input type="text" id="fplace" value="${esc(f.place)}" placeholder="${esc(t('placePh'))}" aria-label="${esc(t('s3'))}"><button type="button" class="locbtn" data-act="loc" aria-label="${esc(t('useLoc'))}" title="${esc(t('useLoc'))}"><svg width="32" height="32" viewBox="0 0 24 24" aria-hidden="true"><path fill="#3A2A1E" d="M12 1.2c-4.3 0-7.8 3.4-7.8 7.7 0 5.5 6.4 12.600 7.200 13.400.3.3.9.3 1.200 0 .8-.8 7.200-7.900 7.200-13.400 0-4.300-3.500-7.700-7.800-7.700z"/><g transform="translate(7.1 4.2) scale(.155)" fill="#FFD770"><ellipse cx="14" cy="29" rx="5.5" ry="7.5" transform="rotate(-22 14 29)"/><ellipse cx="25" cy="17" rx="6" ry="8.5" transform="rotate(-8 25 17)"/><ellipse cx="39" cy="17" rx="6" ry="8.5" transform="rotate(8 39 17)"/><ellipse cx="50" cy="29" rx="5.5" ry="7.5" transform="rotate(22 50 29)"/><path d="M32 29c-8 0-16.500 9-16.500 17.500 0 6 5 8.500 9.500 7.500 3-.7 4.500-2 7-2s4 1.300 7 2c4.500 1 9.500-1.500 9.500-7.500C48.500 38 40 29 32 29z"/></g></svg></button></div><div id="sug" class="sug"></div><div class="hint">${t('locHint')}</div>
<div class="lbl" style="margin-top:16px"><label for="fdesc">${t('s4')}</label></div><textarea id="fdesc" rows="3" placeholder="${esc(t('descPh'))}">${esc(f.desc)}</textarea>
<div style="margin-top:16px"><button class="btn" data-act="search">${t('searchOwner')}</button></div></div>`}
async function vResults(){const f=tmp.find;if(!f||!f.species)return vFound();const res=await DB.match(f,tmp.tab,S.country);
return `${head(t('resultsTitle'),`${speciesName(f.species)} · ${f.place||'–'}`,'#/found')}<div class="pad"><div class="field" style="margin:0 0 12px"><label for="bc">${t('showing')}</label>${countrySel('bc',S.country)}</div><div class="seg">${['area','city','country'].map(k=>`<button data-act="tab" data-v="${k}" class="${tmp.tab===k?'on':''}">${t(k)}</button>`).join('')}</div>
${res.length?res.map(p=>{const n=p.common.length;const sim=n>=2?'simHigh':n===1?'simMid':'simLow';return petCard(p,{hl:n>=2,tag:`<span class="tag" style="background:${n>=2?'var(--y)':'var(--lc)'}">${t(sim)}</span>`,body:`<div class="info" style="margin-top:6px;padding:8px 10px"><b>${t('why')}</b> ${n?esc(t('sameWords'))+' '+esc(p.common.join(', ')):esc(t('noCommon'))}</div>`})}).join(''):`<div class="info warn">${t('emptyRes')}</div>`}
<div class="info warn">${t('help')}</div><div class="hint" style="margin-top:10px">${t('matchNote')}</div>
<div style="margin-top:14px;display:flex;flex-direction:column;gap:8px">${S.user?`<button class="btn sec small" data-act="saveFind">${t('saveFind')}</button>`:''}<a class="btn sec small" href="#/found">${t('changeSearch')}</a></div></div>`}
function needLogin(next){tmp.next=next;location.hash='#/login'}
async function vLogin(){const reg=tmp.loginMode==='reg';return `${head(t('loginTitle'),t('loginSub'),'#/')}<div class="pad"><form data-form="login"><div class="field"><label for="em">${t('email')}</label><input type="email" id="em" autocomplete="email"></div>${reg?`<div class="field"><label for="rc">${t('homeCountry')}</label>${countrySel('rc',S.country)}<div class="hint">${t('homeCountryHint')}</div></div>`:''}<div class="field"><label for="pw">${t('password')}</label><input type="password" id="pw" autocomplete="${reg?'new':'current'}-password"></div><div style="margin-top:16px"><button class="btn" type="submit">${t(reg?'register':'login')}</button></div></form>
<p style="text-align:center"><button class="chip" style="border:0;background:none;text-decoration:underline" data-act="loginMode">${t(reg?'regSwitch':'loginSwitch')}</button></p><p style="text-align:center;margin-top:0"><button class="chip" style="border:0;background:none;text-decoration:underline" data-act="forgot">${t('forgot')}</button></p></div>`}
async function vReset(){return `${head(t('resetTitle'),'','#/')}<div class="pad"><form data-form="reset"><div class="field"><label for="np">${t('newPw')}</label><input type="password" id="np" autocomplete="new-password"></div><div style="margin-top:16px"><button class="btn" type="submit">${t('save')}</button></div></form></div>`}
async function vMine(){const ps=await DB.myPets();return `${topbar(t('mineTitle'),S.user.name)}<div class="pad">${S.user.paused?`<div class="info warn">${t('paused')}</div>`:''}<a class="btn" href="#/addpet">${t('addPet')}</a>${ps.length?'':`<div class="info">${t('noPets')}</div>`}
${ps.map(p=>`<div class="card" style="flex-direction:column"><div style="display:flex;gap:12px"><div class="ph" style="width:72px;height:72px">${photoOf(p)}</div><div class="grow"><div style="display:flex;justify-content:space-between;align-items:center"><a class="name" href="#/pet/${p.id}">${esc(p.name)}</a>${tagOf(p)}</div><span class="muted">${esc(speciesName(p.species))} · ${esc(p.color)}</span>${p.status==='lost'?`<span class="muted">${esc(p.place)}, ${esc(p.city)} · ${esc(fmtDate(p.date))}</span>`:''}</div></div>
<div class="row" style="margin-top:10px">${p.status!=='lost'?`<button class="chip" data-act="lostForm" data-v="${p.id}">${t('setLost')}</button>`:`<button class="chip on" data-act="setFound" data-v="${p.id}">${t('setFound')}</button>`}${p.status!=='registered'?`<button class="chip" data-act="setReg" data-v="${p.id}">${t('setReg')}</button>`:''}<a class="chip" style="display:flex;align-items:center" href="#/edit/${p.id}">${t('edit')}</a><button class="chip" style="color:var(--ct)" data-act="delPet" data-v="${p.id}">${t('del')}</button></div>
${tmp.lostFor===p.id?`<div class="sep"></div><div class="lbl">${t('lostForm')}</div><div class="field" style="margin-top:0"><label for="lp">${t('seenLast')}</label><div class="locrow"><input type="text" id="lp" autocomplete="off" placeholder="${esc(t('seenPh'))}"><button type="button" class="locbtn" data-act="locLost" aria-label="${esc(t('useLoc'))}" title="${esc(t('useLoc'))}"><svg width="32" height="32" viewBox="0 0 24 24" aria-hidden="true"><path fill="#3A2A1E" d="M12 1.2c-4.3 0-7.8 3.4-7.8 7.7 0 5.5 6.4 12.600 7.200 13.400.3.3.9.3 1.200 0 .8-.8 7.200-7.900 7.200-13.400 0-4.300-3.500-7.700-7.800-7.700z"/><g transform="translate(7.1 4.2) scale(.155)" fill="#FFD770"><ellipse cx="14" cy="29" rx="5.5" ry="7.5" transform="rotate(-22 14 29)"/><ellipse cx="25" cy="17" rx="6" ry="8.5" transform="rotate(-8 25 17)"/><ellipse cx="39" cy="17" rx="6" ry="8.5" transform="rotate(8 39 17)"/><ellipse cx="50" cy="29" rx="5.5" ry="7.5" transform="rotate(22 50 29)"/><path d="M32 29c-8 0-16.500 9-16.500 17.500 0 6 5 8.500 9.500 7.500 3-.7 4.500-2 7-2s4 1.300 7 2c4.500 1 9.500-1.500 9.500-7.500C48.500 38 40 29 32 29z"/></g></svg></button></div><div id="sug" class="sug"></div></div><div class="field"><label for="ld">${t('dateLost')}</label><input type="date" id="ld" max="${today()}" value="${today()}"></div><div class="field"><label for="lcirc">${t('circ')}</label><textarea id="lcirc" rows="3"></textarea></div><div class="row" style="margin-top:12px"><button class="btn small" style="width:auto;padding:0 20px" data-act="saveLost" data-v="${p.id}">${t('saveLost')}</button><button class="btn sec small" style="width:auto;padding:0 20px" data-act="cancelLost">${t('cancel')}</button></div>`:''}</div>`).join('')}</div>`}
async function vAdd(id){const p=id?await DB.myPet(id):(tmp.petForm||null);tmp.bsInit=p?p.breed:'';tmp.colorInit=p?p.color:'';if(id&&!p)return head(t('notFound'),'','#/mine');const v=k=>esc(p&&p[k]!=null?p[k]:'');const sel=(a,b)=>p&&p[a]===b?'selected':'';
return `${head(t(id?'editPet':'addTitle'),'','#/mine')}<div class="pad">${id?'':`<div class="lbl" style="margin-top:6px">${t('photosNeed')}</div><div class="thumbs"><label class="add"><input type="file" accept="image/*" capture="environment" hidden data-file="pet">${sz(ic.cam,26)}${t('takePhoto')}</label>${tmp.petPhotos.map((s,i)=>`<div class="thumb"><img src="${esc(s.url)}" alt=""><button data-act="rmPet" data-v="${i}" aria-label="${esc(t('removePhoto'))}">×</button></div>`).join('')}<label class="add" style="background:#fff;border:1.5px solid var(--db)"><input type="file" accept="image/*" multiple hidden data-file="pet"><span style="font-size:24px">+</span>${t('pickPhotos')}</label></div>`}
<div class="field"><label for="an">${t('fName')}</label><input type="text" id="an" maxlength="60" value="${v('name')}"></div><div class="field"><label for="asp">${t('species')}</label><select id="asp"><option value="" disabled ${p&&p.species?'':'selected'}>${t('chooseSpecies')}</option><option value="cat" ${sel('species','cat')}>${t('cat')}</option><option value="dog" ${sel('species','dog')}>${t('dog')}</option><option value="bird" ${sel('species','bird')}>${t('bird')}</option><option value="rabbit" ${sel('species','rabbit')}>${t('rabbit')}</option><option value="rodent" ${sel('species','rodent')}>${t('rodent')}</option><option value="reptile" ${sel('species','reptile')}>${t('reptile')}</option><option value="other" ${sel('species','other')}>${t('other')}</option></select></div>
<div class="field"><label for="abi">${t('fBreed')}</label><div id="breedbox"></div></div><div class="field"><label>${t('fColor')}</label><div id="colorbox"></div></div>
<div class="field"><label for="ase">${t('sex')}</label><select id="ase"><option value="f" ${sel('sex','f')}>${t('female')}</option><option value="m" ${sel('sex','m')}>${t('male')}</option><option value="unknown" ${sel('sex','unknown')}>${t('unknown')}</option></select></div>
<div class="field"><label for="aa">${t('fAge')}</label><input type="number" id="aa" min="0" max="40" value="${v('age')}"></div><div class="field"><label for="am">${t('fMarks')}</label><textarea id="am" rows="2" maxlength="500">${v('marks')}</textarea></div><div class="field"><label for="ad">${t('fDesc')}</label><textarea id="ad" rows="3" maxlength="2000">${v('desc')}</textarea></div><div class="field"><label for="ach">${t('fChip')}</label><input type="text" id="ach" maxlength="40" value="${v('chip')}"></div>
<div style="margin-top:16px"><button class="btn" data-act="savePet" data-v="${id||''}">${t('save')}</button></div></div>`}
const nameOf=(r,me)=>{const o=r.finder_id===me?r.owner:r.finder;return o&&o.username?o.username:t('deletedUser')};
async function vMsgs(){const rs=await DB.requests();const me=S.user.id;return `${topbar(t('msgTitle'))}<div class="pad">${rs.length?'':`<div class="info">${t('noMsgs')}</div>`}${rs.map(r=>{const rec=r.owner_id===me;
return `<div class="card" style="flex-direction:column"><div style="display:flex;justify-content:space-between"><span class="name">${esc(r.pet_name)}</span><span class="tag t-found">${t(r.status)}</span></div><span class="muted">${t(rec?'received':'sent')} · ${esc(nameOf(r,me))}</span><div style="font-size:15px;font-weight:600;margin-top:4px;word-break:break-word">${esc(r.intro)}</div>${r.pet_id?'':`<span class="muted">${t('archivedPet')}</span>`}
<div class="row" style="margin-top:10px">${r.status==='pending'&&rec?`<button class="chip on" data-act="accept" data-v="${r.id}">${t('accept')}</button><button class="chip" data-act="decline" data-v="${r.id}">${t('decline')}</button>`:''}${r.status==='pending'&&!rec?`<button class="chip" data-act="revoke" data-v="${r.id}">${t('revoke')}</button>`:''}${r.status==='accepted'?`<a class="chip" style="display:flex;align-items:center;font-weight:800;background:var(--y)" href="#/chat/${r.id}">${t('openChat')}</a>`:''}</div></div>`}).join('')}</div>`}
async function vChat(id){const rs=await DB.requests();const r=rs.find(x=>x.id===id);if(!r||r.status!=='accepted')return head(t('notFound'),'','#/messages');const me=S.user.id;const other=r.finder_id===me?r.owner_id:r.finder_id;
const [msgs,blocked]=await Promise.all([DB.messages(id),DB.blockedIds()]);DB.markRead(id).then(refreshBadge).catch(()=>{});const bl=other&&blocked.includes(other);
return `${head(t('chatTitle'),nameOf(r,me),'#/messages')}<div class="pad"><div class="msgs" id="msgs">${msgs.map(m=>`<div class="msg ${m.sender_id===me?'me':'them'}">${esc(m.body)}<small>${new Date(m.created_at).toLocaleString(S.lang==='en'?'en-GB':'sv-SE',{hour:'2-digit',minute:'2-digit',day:'numeric',month:'short'})}</small></div>`).join('')}</div>
${bl?`<div class="info warn">${t('blockedChat')}</div>`:other?`<form class="sendbar" data-form="chat" data-v="${id}"><input type="text" id="cm" placeholder="${esc(t('msgPh'))}" aria-label="${esc(t('msgPh'))}" maxlength="2000" autocomplete="off"><button class="btn" type="submit">${t('send')}</button></form><div class="row" style="margin-top:12px"><button class="chip" style="color:var(--ct)" data-act="block" data-v="${id}">${t('block')}</button></div>`:`<div class="info">${t('deletedUser')}</div>`}</div>`}
async function vProfile(){const u=S.user;return `${topbar(t('profTitle'))}<div class="pad"><div class="field" style="margin-top:0"><label for="un">${t('username')}</label><input type="text" id="un" value="${esc(u.name)}" maxlength="20"><div class="hint">${t('usernameHint')}</div></div><button class="btn small" style="margin-top:10px" data-act="saveName">${t('saveName')}</button>
<div class="sep"></div><div class="field" style="margin-top:0"><label for="hc">${t('homeCountry')}</label>${countrySel('hc',u.country)}</div><button class="btn sec small" style="margin-top:10px" data-act="saveCountry">${t('saveCountry')}</button>
<div class="sep"></div><div class="lbl">${t('language')}</div><div class="row"><button class="chip ${S.lang==='sv'?'on':''}" data-act="lang" data-v="sv">Svenska</button><button class="chip ${S.lang==='en'?'on':''}" data-act="lang" data-v="en">English</button></div>
<div class="sep"></div>${u.paused?`<div class="info warn">${t('paused')}</div>`:''}<button class="btn sec" data-act="pause">${t(u.paused?'resume':'pause')}</button><button class="btn danger" style="margin-top:10px" data-act="delAcc">${t('delAcc')}</button><button class="btn sec" style="margin-top:10px" data-act="logout">${t('logout')}</button><div class="info">${t('privacy')}</div></div>`}
/* ---------- router ---------- */
const PROTECTED=['mine','addpet','edit','messages','chat','profile','contact'];
async function route(){const tok=++routeTok;const h=location.hash.replace(/^#\/?/,'');const [r,a]=h.split('/');
if(PROTECTED.includes(r)&&!S.user){tmp.next='#/'+h;r!=='login'&&(location.hash='#/login');return}
let html;try{switch(r){case '':html=await vList();break;case 'pet':html=await vPet(a);break;case 'contact':html=await vContact(a);break;case 'found':html=await vFound();break;case 'results':html=await vResults();break;case 'login':html=S.user?await vProfile():await vLogin();break;case 'reset':html=await vReset();break;case 'mine':html=await vMine();break;case 'addpet':html=await vAdd();break;case 'edit':html=await vAdd(a);break;case 'messages':html=await vMsgs();break;case 'chat':html=await vChat(a);break;case 'profile':html=await vProfile();break;default:html=head(t('notFound'),'','#/')}}
catch(e){html=head(t('appname'),'','#/')+`<div class="pad"><div class="info warn">${esc(errMsg(e))}</div></div>`}
if(tok!==routeTok)return;document.documentElement.lang=S.lang;$('#app').innerHTML=html;if(r==='addpet'||r==='edit')initBreed();nav(r==='login'&&S.user?'profile':r);if(r==='')fillList();window.scrollTo(0,0);const m=$('#msgs');if(m)window.scrollTo(0,document.body.scrollHeight)}
async function rerender(keep){const y=window.scrollY;await route();if(keep)window.scrollTo(0,y)}
async function refreshBadge(){if(!S.user){S.unread=0;return}try{S.unread=await DB.unreadCount()}catch(e){}const r=location.hash.replace(/^#\/?/,'').split('/')[0];nav(r==='login'&&S.user?'profile':r)}
/* ---------- bilder ---------- */
function shrink(file){return new Promise((ok,no)=>{if(!file.type.startsWith('image/')||file.size>5*1024*1024)return no();const url=URL.createObjectURL(file);const im=new Image();im.onload=()=>{const m=1024,k=Math.min(1,m/Math.max(im.width,im.height));const c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);URL.revokeObjectURL(url);c.toBlob(b=>b?ok({blob:b,url:URL.createObjectURL(b)}):no(),'image/jpeg',.82)};im.onerror=()=>{URL.revokeObjectURL(url);no()};im.src=url})}
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='rc'||el.id==='hc'){const f=$('#'+el.id+'-flag');if(f)f.textContent=flag(el.value);return}
if(el.id==='bc'){S.country=el.value;S.countryTouched=true;try{localStorage.setItem('dh-country',el.value)}catch(e){}rerender(true);return}
if(el.id==='asp'){tmp.bs={mixed:false,list:[]};renderBreed();return}if(!el.dataset||!el.dataset.file)return;const list=el.dataset.file==='found'?tmp.foundPhotos:tmp.petPhotos;saveFields();for(const f of el.files){try{list.push(await shrink(f))}catch(x){toast(t('badFile'))}}rerender(true)});
function saveFields(){const v=id=>{const e=document.getElementById(id);return e?e.value:undefined};if(location.hash.startsWith('#/addpet')&&$('#an')){tmp.petForm={name:v('an'),species:v('asp'),breed:buildBreed(),color:buildColor(),sex:v('ase'),age:v('aa'),marks:v('am'),desc:v('ad'),chip:v('ach')}};if(location.hash.startsWith('#/found')){tmp.find=tmp.find||{species:'',place:'',desc:''};if(v('fplace')!==undefined)tmp.find.place=v('fplace');if(v('fdesc')!==undefined)tmp.find.desc=v('fdesc')}}
const streetOf=a=>a.road?a.road+(a.house_number?' '+a.house_number:''):(a.pedestrian||a.footway||a.path||a.square||'');
const areaOf=a=>a.suburb||a.neighbourhood||a.quarter||a.city_district||a.village||a.town||a.city||a.municipality||'';
const cityOf=a=>a.city||a.town||a.municipality||a.village||a.county||'';
function mkPlace(a){const street=streetOf(a),area=areaOf(a),city=cityOf(a)||area;const parts=[street,area&&area!==street&&area!==city?area:''].filter(Boolean);const place=(parts.join(', ')||area||city).slice(0,110);return{place,city:city||place,area:area||city,country:String(a.country_code||'').toUpperCase(),label:place===city?place:place+', '+city}}
async function reverseAddr(lat,lon){const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&zoom=18&addressdetails=1&accept-language=${S.lang}&lat=${lat}&lon=${lon}`);if(!r.ok)throw 0;const j=await r.json();if(!j.address)throw 0;return mkPlace(j.address)}
async function reverseGeo(lat,lon){const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&zoom=14&accept-language=${S.lang}&lat=${lat}&lon=${lon}`);if(!r.ok)throw 0;const a=(await r.json()).address||{};const area=a.suburb||a.neighbourhood||a.quarter||a.village||a.town||a.city||'';const city=a.city||a.town||a.municipality||a.village||'';return[area,city]}
/* ---------- handlingar ---------- */
const val=id=>($('#'+id)||{value:''}).value.trim();
const A={
lang(v){S.lang=v;try{localStorage.setItem('dh-lang',v)}catch(e){}saveFields();rerender(true)},
sp(v){tmp.sp=v;tmp.qb='';rerender(true)},togFilters(){tmp.fopen=!tmp.fopen;rerender(true)},setSex(v){tmp.qs=v;rerender(true)},clearFilters(){tmp.qb='';tmp.qc='';tmp.qp='';tmp.qs='';tmp.qd='';rerender(true)},phPrev(){tmp.photoIdx=Math.max(0,tmp.photoIdx-1);rerender(true)},phNext(){tmp.photoIdx++;rerender(true)},ph(v){tmp.photoIdx=+v;rerender(true)},
fsp(v){saveFields();tmp.find=tmp.find||{species:'',place:'',desc:''};tmp.find.species=v;rerender(true)},
rmFound(v){saveFields();tmp.foundPhotos.splice(+v,1);rerender(true)},rmPet(v){saveFields();tmp.petPhotos.splice(+v,1);rerender(true)},
loc(){saveFields();tmp.find=tmp.find||{species:'',place:'',desc:''};openMap(m=>{tmp.find.place=m.area||m.city;rerender(true)})},
search(){saveFields();const f=tmp.find||{};if(!f.species)return toast(t('needSpecies'));if(!(f.place||'').trim())return toast(t('needPlace'));tmp.tab='area';location.hash='#/results'},
locLost(){openMap(m=>setLostLoc(m.place,m.city,m.country))},
pickBreed(v){addBreed(v)},togColor(v){const c=tmp.colors=tmp.colors||[];const i=c.indexOf(v);if(i>=0)c.splice(i,1);else{if(c.length>=4)return toast(t('colorMax'));c.push(v)}renderColors()},unmix(){tmp.bs={mixed:false,list:[]};renderBreed()},rmBreed(v){const bs=tmp.bs;if(bs.mixed&&bs.list.length===0)return;bs.list.splice(+v,1);if(!bs.list.length&&bs.mixed&&false)bs.mixed=false;renderBreed()},locFilter(){openMap(m=>{tmp.qp=m.area||m.city;const q=$('#qp');if(q)q.value=tmp.qp;fillList()})},mapOk(){mapConfirm()},mapCancel(){mapClose()},
pickSug(v){const x=tmp.sugs[+v];if(!x)return;if(tmp.sugField==='qp'){tmp.qp=x.area||x.city;const q=$('#qp');if(q)q.value=tmp.qp;clearSug();fillList();return}
if(tmp.sugField==='fplace'){tmp.find=tmp.find||{species:'',place:'',desc:''};tmp.find.place=x.area||x.city;const f=$('#fplace');if(f)f.value=tmp.find.place;clearSug()}else setLostLoc(x.place,x.city,x.country)},
tab(v){tmp.tab=v;rerender(true)},
async saveFind(){await DB.saveFind(S.user.id,tmp.find,tmp.foundPhotos.map(p=>p.blob));toast(t('findSaved'))},
async sendReq(id){const txt=val('intro');if(!txt)return toast(t('needOne'));await DB.sendRequest(id,txt);toast(t('reqSent'));location.hash='#/messages'},
async accept(id){await DB.respond(id,true);location.hash='#/chat/'+id},
async decline(id){await DB.respond(id,false);refreshBadge();rerender(true)},
async revoke(id){await DB.revoke(id);rerender(true)},
async block(id){if(!confirm(t('confirmBlock')))return;await DB.block(id);rerender(true)},
loginMode(){tmp.loginMode=tmp.loginMode==='reg'?'login':'reg';rerender()},
async forgot(){const em=val('em');if(!/^\S+@\S+\.\S+$/.test(em))return toast(t('typeEmail'));await DB.resetPassword(em);toast(t('resetSent'))},
lostForm(id){tmp.lostFor=id;rerender(true)},cancelLost(){tmp.lostFor=null;rerender(true)},
async saveLost(id){const pl=val('lp'),d=val('ld'),c=val('lcirc');if(!pl||!c||!d||d>today())return toast(t('needLostFields'));
const L=tmp.lostLoc&&tmp.lostLoc.label===pl?tmp.lostLoc:null;if(!L||!L.country){onPlaceInput(pl,'lp');return toast(t('pickAddress'))}
toast(t('checkingGps'));const pos=await getPos();if(!pos)return toast(t('needGps'));let dev;try{dev=(await reverseAddr(pos[0],pos[1])).country}catch(e){return toast(t('needGps'))}
if(!dev||dev!==L.country)return toast(t('wrongCountry').replace('{a}',cName(L.country)).replace('{b}',cName(dev||'?')));
await DB.reportLost(id,L.place,L.city,d,c,L.country,dev);tmp.lostLoc=null;tmp.lostFor=null;toast(t('nowLost'));rerender(true)},
async setFound(id){await DB.markFound(id);toast(t('nowFound'));rerender(true)},
async setReg(id){await DB.setRegistered(id);rerender(true)},
async delPet(id){if(!confirm(t('confirmDel')))return;await DB.deletePet(id);rerender(true)},
async savePet(id){const f={name:val('an'),species:$('#asp').value,breed:buildBreed(),color:buildColor(),sex:$('#ase').value,age:val('aa'),marks:val('am'),desc:val('ad'),chip:val('ach')};
if(!f.name||!f.color||!f.species)return toast(t('needPetFields'));
if(id){await DB.updatePet(id,f);toast(t('saved'));location.hash='#/mine';return}
if(tmp.petPhotos.length<2)return toast(t('needPhotos'));toast(t('posting'));await DB.addPet(S.user.id,f,tmp.petPhotos.map(p=>p.blob));tmp.petPhotos=[];tmp.petForm=null;toast(t('petSaved'));location.hash='#/mine'},
async saveCountry(){const c=$('#hc').value;let local=false;try{await DB.setHomeCountry(c)}catch(e){if(/function|schema cache|p_country|home_country/i.test(String((e&&e.message)||'')))local=true;else return toast(errMsg(e))}S.user.country=c;S.country=c;S.countryTouched=true;try{localStorage.setItem('dh-country',c)}catch(e){}toast(t(local?'dbOld':'countrySaved'));rerender(true)},
async saveName(){const n=val('un');if(!/^[A-Za-z0-9åäöÅÄÖ]{3,20}$/.test(n))return toast(t('nameBad'));try{await DB.changeUsername(n)}catch(e){return toast(/upptaget|unique|duplicate/i.test(e.message)?t('nameTaken'):errMsg(e))}S.user.name=n;toast(t('nameSaved'));rerender(true)},
async pause(){await DB.setPaused(!S.user.paused);S.user.paused=!S.user.paused;toast(t(S.user.paused?'pauseDone':'resumeDone'));rerender(true)},
async delAcc(){if(!confirm(t('confirmDelAcc')))return;await DB.deleteAccount();await loadUser();toast(t('accDeleted'));location.hash='#/';rerender()},
async logout(){await DB.signOut();await loadUser();tmp.next='';location.hash='#/';rerender()}};
function setLostLoc(place,city,country){const label=place===city?place:place+', '+city;tmp.lostLoc={place,city,label,country};const p=$('#lp');if(p)p.value=label;clearSug()}
function clearSug(){tmp.sugs=[];const e=$('#sug');if(e)e.innerHTML=''}
let sugTimer,sugCtl,sugLast=0;
async function searchPlaces(q){const r=await fetch('https://photon.komoot.io/api/?limit=10'+(cBox(S.country)?'&bbox='+cBox(S.country):'')+'&q='+encodeURIComponent(q),{signal:sugCtl.signal});if(!r.ok)throw 0;const seen={},out=[];
for(const f of (await r.json()).features||[]){const p=f.properties||{};if(!COUNTRIES.some(x=>x.c===p.countrycode))continue;const ty=p.type||'';const a={country_code:p.countrycode};
if(p.street){a.road=p.street;if(p.housenumber)a.house_number=p.housenumber}else if(ty==='street')a.road=p.name;else if(p.name&&!['city','district','locality','county','state','country','house'].includes(ty))a.pedestrian=p.name;
a.suburb=p.district||p.locality||(['district','locality'].includes(ty)?p.name:'');a.city=p.city||(ty==='city'?p.name:'')||p.county||'';
if(!streetOf(a)&&!areaOf(a)&&!cityOf(a))continue;const m=mkPlace(a);if(seen[m.label])continue;seen[m.label]=1;out.push(m)}return out}
function onPlaceInput(v,fid){fid=fid||'lp';tmp.sugField=fid;clearTimeout(sugTimer);if(fid==='lp'&&tmp.lostLoc&&tmp.lostLoc.label!==v)tmp.lostLoc=null;const e0=$('#sug');if(v.trim().length<2){clearSug();return}
sugTimer=setTimeout(async()=>{if(sugCtl)sugCtl.abort();sugCtl=new AbortController();
try{const res=await searchPlaces(v.trim());const e=$('#sug');if(!e||!$('#'+fid)||$('#'+fid).value.trim()!==v.trim())return;tmp.sugs=res;e.innerHTML=res.length?res.map((x,i)=>`<button type="button" data-act="pickSug" data-v="${i}">${esc(x.label)}</button>`).join(''):`<div class="hint" style="padding:10px 14px;margin:0">${t('sugNone')}</div>`}catch(x){if(x&&x.name==='AbortError')return;const e=$('#sug');if(e)e.innerHTML=`<div class="hint" style="padding:10px 14px;margin:0">${t('sugFail')}</div>`}},350)}
