const COLORS=[['Svart','Black'],['Vit','White'],['Grå','Grey'],['Brun','Brown'],['Chokladbrun','Chocolate'],['Beige','Beige'],['Gräddvit','Cream'],['Gyllene','Golden'],['Gul','Yellow'],['Röd','Red'],['Rödbrun','Reddish brown'],['Orange','Orange'],['Blå (grå-blå)','Blue (grey-blue)'],['Silver','Silver'],['Svartvit','Black and white'],['Trefärgad (kalikå)','Tricolour (calico)'],['Tigrerad','Tabby (striped)'],['Sköldpadd','Tortoiseshell'],['Brindle (randig)','Brindle'],['Fläckig','Spotted'],['Merle','Merle'],['Sabel','Sable']];
const colorDisp=c=>{const x=COLORS.find(y=>y[0]===c);return x?x[S.lang==='en'?1:0]:c};
const parseColors=c=>String(c||'').split(/,\s*(?![^()]*\))/).map(x=>x.trim()).filter(Boolean);
function buildColor(){return (tmp.colors||[]).join(', ').slice(0,80)}
function renderColors(){const b=$('#colorbox');if(!b)return;const sel=tmp.colors||[];const extra=sel.filter(c=>!COLORS.some(x=>x[0]===c));
b.innerHTML=`<div class="row">${COLORS.map(x=>x[0]).concat(extra).map(c=>`<button type="button" class="chip ${sel.includes(c)?'on':''}" data-act="togColor" data-v="${esc(c)}" aria-pressed="${sel.includes(c)}">${esc(colorDisp(c))}</button>`).join('')}</div><div class="hint">${t('colorHint')}</div>`}
