const BIRDS=['Agapornis (dvärgpapegoja)','Amazonpapegoja','Ara','Bengalfink','Duva','Dvärghöna','Gouldamadin','Grå jako','Höna','Japansk bergfink','Kakadua','Kanariefågel','Kalkon','Nymfparakit','Rosenparakit','Sebrafink','Tamanka','Undulat','Vaktel','Parakit (annan)','Papegoja (annan)'];
const RABBITS=['Angorakanin','Dvärgkanin','Dvärgvädur','Hermelinkanin','Hängöronkanin (vädur)','Holländsk dvärgkanin','Lejonhuvudkanin','Rexkanin','Kanin (annan)'];
const RODENTS=['Chinchilla','Degu','Gerbil (ökenråtta)','Jordekorre','Kinesisk hamster','Marsvin','Mus','Råtta','Rysk dvärghamster','Syrisk hamster (guldhamster)','Dvärghamster (annan)'];
const REPTILES=['Boa constrictor','Bartagam (skäggagam)','Blåtungad skink','Grekisk landsköldpadda','Grön leguan','Jemenkameleont','Kameleont (annan)','Krönad gecko','Kungsorm','Kungspyton','Leopardgecko','Majsorm','Mjölkorm','Ormhalssköldpadda','Rysk landsköldpadda','Rödörad vattensköldpadda','Smyckesköldpadda','Sköldpadda (annan)','Tegu','Varan','Orm (annan)','Ödla (annan)'];
const BREEDS=sp=>sp==='cat'?CATS:sp==='dog'?DOGS:sp==='bird'?BIRDS:sp==='rabbit'?RABBITS:sp==='rodent'?RODENTS:sp==='reptile'?REPTILES:[];
const FREE=sp=>sp!=='cat'&&sp!=='dog';
const breedDisp=b=>{if(!b)return'';if(b==='Huskatt')return t('houseCat');if(b==='Okänd')return t('unknownBreed');if(b.startsWith('Blandras'))return t('mixedBreed')+b.slice(8);return b};
function parseBreed(b){b=b||'';if(b.startsWith('Blandras'))return{mixed:true,list:b.slice(8).replace(/^:\s*/,'').split(/,\s*/).filter(Boolean)};return{mixed:false,list:b?[b]:[]}}
function buildBreed(){const bs=tmp.bs||{mixed:false,list:[]};const e=$('#abi');const txt=e?e.value.trim():'';const list=bs.list.slice();const spx=($('#asp')||{}).value;if(txt&&spx&&FREE(spx)&&!list.includes(txt)&&(bs.mixed||!list.length))list.push(txt);
const out=bs.mixed?(list.length?'Blandras: '+list.join(', '):'Blandras'):(list[0]||'');return out.slice(0,80)}
function initBreed(){tmp.bs=parseBreed(tmp.bsInit||'');tmp.colors=parseColors(tmp.colorInit||'');renderBreed();renderColors()}
function renderBreed(){const box=$('#breedbox');if(!box)return;const bs=tmp.bs;const sp=($('#asp')||{}).value||'';if(!sp){box.innerHTML=`<input type="text" disabled placeholder="${esc(t('speciesFirst'))}"><div class="hint">${t('speciesFirst')}</div>`;return}const one=!bs.mixed&&bs.list.length;
box.innerHTML=`${bs.mixed?`<div class="hint" style="margin:0 0 6px"><b>${t('mixedBreed')}</b> – ${t('mixedHint')} <button type="button" data-act="unmix" style="border:0;background:none;text-decoration:underline;font:inherit;cursor:pointer;color:var(--ct)">${t('unmix')}</button></div>`:''}${bs.list.length?`<div class="row" style="margin-bottom:8px">${bs.list.map((b,i)=>`<span class="chip on" style="display:inline-flex;gap:6px;align-items:center">${esc(breedDisp(b))}<button type="button" data-act="rmBreed" data-v="${i}" aria-label="${esc(t('removePhoto'))}" style="border:0;background:none;font-size:18px;line-height:1;cursor:pointer;color:inherit;padding:0">×</button></span>`).join('')}</div>`:''}${one?'':`<input type="text" id="abi" autocomplete="off" maxlength="60" placeholder="${esc(t(sp==='other'?(bs.mixed?'addMoreBreed':'breedPhOther'):FREE(sp)?'breedPhType':(bs.mixed?'addMoreBreed':'breedPh')))}"><div id="bsug" class="sug"></div>`}`}
function renderBsug(){const e=$('#abi'),box=$('#bsug');if(!e||!box)return;const bs=tmp.bs;const sp=($('#asp')||{}).value;const q=e.value.trim().toLowerCase();let items=[];
const special=[];if(!bs.mixed&&!bs.list.length){if(sp==='cat')special.push('Huskatt');if(sp==='cat'||sp==='dog')special.push('Blandras');special.push('Okänd')}
const lbl=x=>x==='Blandras'?t('mixedBreed'):breedDisp(x);
const all=special.concat(BREEDS(sp)).filter(x=>!bs.list.includes(x));
const m=q?all.filter(x=>lbl(x).toLowerCase().includes(q)):all;const sorted=q?m.sort((a,b)=>(lbl(a).toLowerCase().startsWith(q)?0:1)-(lbl(b).toLowerCase().startsWith(q)?0:1)):m;
items=sorted.slice(0,q?8:special.length+5);
const rows=items.map(x=>`<button type="button" data-act="pickBreed" data-v="${esc(x)}">${esc(lbl(x))}</button>`);
if(q&&FREE(sp)&&!all.some(x=>lbl(x).toLowerCase()===q))rows.push(`<button type="button" data-act="pickBreed" data-v="${esc(e.value.trim())}">${esc(t('addBreed'))} "${esc(e.value.trim())}"</button>`);
box.innerHTML=rows.join('')}
function addBreed(v){const bs=tmp.bs;v=(v||'').trim();if(!v)return;
if(v==='Blandras'){bs.mixed=true;bs.list=[]}
else if(bs.mixed){if(!bs.list.includes(v)){const nxt='Blandras: '+bs.list.concat(v).join(', ');if(nxt.length>80)return toast(t('breedMax'));bs.list.push(v)}}
else bs.list=[v];
renderBreed();const e=$('#abi');if(e&&bs.mixed)e.focus()}
/* ---------- karta för att finjustera plats (Leaflet + OpenStreetMap, laddas först när den behövs) ---------- */
let MAP=null;
function loadLeaflet(){if(window.L)return Promise.resolve();return new Promise((ok,no)=>{const l=document.createElement('link');l.rel='stylesheet';l.href='https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css';document.head.appendChild(l);const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.js';s.onload=ok;s.onerror=no;document.head.appendChild(s)})}
function getPos(){return new Promise(ok=>{if(!navigator.geolocation)return ok(null);navigator.geolocation.getCurrentPosition(p=>ok([p.coords.latitude,p.coords.longitude]),()=>ok(null),{timeout:8000,enableHighAccuracy:true})})}
async function openMap(cb){if(MAP)return;MAP={cb,cur:null,tm:null};toast(t('mapFinding'));let pos,ok=true;
try{[pos]=await Promise.all([getPos(),loadLeaflet()])}catch(e){ok=false}
if(!ok||!window.L){MAP=null;return toast(t('mapFail'))}
const ov=document.createElement('div');ov.id='mapov';ov.setAttribute('role','dialog');ov.setAttribute('aria-modal','true');
ov.innerHTML=`<div class="mh"><b>${esc(t('mapTitle'))}</b><span class="muted">${esc(t(pos?'mapHint':'mapHintNoGps'))}</span></div><div id="map"></div><div class="mf"><div id="mlabel" class="mlabel">${esc(t('mapFinding'))}</div><div class="row"><button class="btn" data-act="mapOk">${esc(t('mapUse'))}</button><button class="btn sec" data-act="mapCancel">${esc(t('cancel'))}</button></div></div>`;
document.body.appendChild(ov);
const start=pos||[62,15];const map=L.map('map',{zoomControl:true}).setView(start,pos?16:5);
L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);
const icon=L.divIcon({className:'pin',html:'<svg width="40" height="52" viewBox="3.6 0.6 16.8 22.8" aria-hidden="true"><path fill="#3A2A1E" d="M12 1.2c-4.3 0-7.8 3.4-7.8 7.7 0 5.5 6.4 12.600 7.200 13.400.3.3.9.3 1.200 0 .8-.8 7.200-7.900 7.200-13.400 0-4.300-3.500-7.700-7.800-7.700z"/><g transform="translate(7.1 4.2) scale(.155)" fill="#FFD770"><ellipse cx="14" cy="29" rx="5.5" ry="7.5" transform="rotate(-22 14 29)"/><ellipse cx="25" cy="17" rx="6" ry="8.5" transform="rotate(-8 25 17)"/><ellipse cx="39" cy="17" rx="6" ry="8.5" transform="rotate(8 39 17)"/><ellipse cx="50" cy="29" rx="5.5" ry="7.5" transform="rotate(22 50 29)"/><path d="M32 29c-8 0-16.500 9-16.500 17.500 0 6 5 8.500 9.500 7.500 3-.7 4.500-2 7-2s4 1.300 7 2c4.500 1 9.500-1.500 9.500-7.500C48.500 38 40 29 32 29z"/></g></svg>',iconSize:[40,52],iconAnchor:[20,51]});
const mk=L.marker(start,{draggable:true,icon}).addTo(map);MAP.map=map;MAP.mk=mk;
const upd=()=>{const ll=mk.getLatLng();MAP.cur=null;const lb=$('#mlabel');if(lb)lb.textContent=t('mapFinding');clearTimeout(MAP.tm);MAP.tm=setTimeout(async()=>{try{const m=await reverseAddr(ll.lat,ll.lng);if(!MAP)return;const name=m.label;MAP.cur=name?m:null;const l2=$('#mlabel');if(l2)l2.textContent=name||t('locNoName')}catch(e){const l2=$('#mlabel');if(l2)l2.textContent=t('locNoName')}},700)};
mk.on('dragend',upd);map.on('click',e=>{mk.setLatLng(e.latlng);upd()});
if(pos)upd();else{const lb=$('#mlabel');if(lb)lb.textContent=t('mapPickHint')}
setTimeout(()=>map.invalidateSize(),50)}
function mapClose(){if(!MAP)return;clearTimeout(MAP.tm);try{MAP.map&&MAP.map.remove()}catch(e){}const o=$('#mapov');if(o)o.remove();MAP=null}
function mapConfirm(){if(!MAP||!MAP.cur)return toast(t('mapWait'));const m=MAP.cur,cb=MAP.cb;mapClose();cb(m)}
document.addEventListener('keydown',e=>{if(e.key==='Escape')mapClose();if(e.key==='Enter'&&e.target.id==='abi'){e.preventDefault();const v=e.target.value.trim();if(v){const sp=($('#asp')||{}).value;if(FREE(sp)){const f1=document.querySelector('#bsug [data-act=pickBreed]');addBreed(f1&&f1.textContent.trim().toLowerCase()===v.toLowerCase()?f1.dataset.v:v)}else{const first=document.querySelector('#bsug [data-act=pickBreed]');if(first)addBreed(first.dataset.v)}}}});
document.addEventListener('focusin',e=>{if(e.target.id==='abi')renderBsug()});
document.addEventListener('click',e=>{if(!e.target.closest('#breedbox')){const b=$('#bsug');if(b)b.innerHTML=''}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b)return;e.preventDefault();const f=A[b.dataset.act];if(!f||tmp.busy)return;tmp.busy=true;try{await f(b.dataset.v)}catch(x){toast(errMsg(x))}finally{tmp.busy=false}});
let sx=null;document.addEventListener('touchstart',e=>{sx=e.target.closest('.hero')?e.touches[0].clientX:null},{passive:true});
document.addEventListener('touchend',e=>{if(sx===null)return;const d=e.changedTouches[0].clientX-sx;sx=null;if(Math.abs(d)<40)return;const b=document.querySelector(d<0?'.hero .arr.r':'.hero .arr.l');if(b)b.click()},{passive:true});
let qTimer;document.addEventListener('input',e=>{if(e.target.id==='qd'){tmp.qd=e.target.value;rerender(true);return}if(e.target.id==='qb'||e.target.id==='qc'||e.target.id==='qp'){tmp[e.target.id]=e.target.value;clearTimeout(qTimer);qTimer=setTimeout(fillList,250);if(e.target.id==='qp')onPlaceInput(e.target.value,'qp')}if(e.target.id==='abi')renderBsug();if(e.target.id==='lp'||e.target.id==='fplace')onPlaceInput(e.target.value,e.target.id);if(e.target.id==='intro'){const c=$('#cnt');if(c)c.textContent=e.target.value.length+' / 2000'}});
document.addEventListener('submit',async e=>{const f=e.target.dataset.form;if(!f)return;e.preventDefault();if(tmp.busy)return;tmp.busy=true;
try{
if(f==='login'){const em=val('em'),pw=$('#pw').value;if(!/^\S+@\S+\.\S+$/.test(em)||pw.length<6)return toast(t('badLogin'));
 if(tmp.loginMode==='reg'){const d=await DB.signUp(em,pw,($('#rc')||{}).value||S.country);if(!d.session)return toast(t('checkEmail'))}else await DB.signIn(em,pw);
 await loadUser();if(!S.user)throw new Error(t('profileFail'));tmp.loginMode='login';toast(t('welcome')+' '+S.user.name);const n=tmp.next||'#/profile';tmp.next='';location.hash=n}
if(f==='reset'){const pw=$('#np').value;if(pw.length<6)return toast(t('badLogin'));await DB.setPassword(pw);toast(t('pwSaved'));location.hash='#/profile'}
if(f==='chat'){const v=$('#cm').value.trim();if(!v)return;await DB.send(e.target.dataset.v,v);$('#cm').value='';await rerender()}
}catch(x){toast(errMsg(x))}finally{tmp.busy=false}});
/* ---------- start, inloggning och realtid ---------- */
async function loadUser(){let p=null;try{p=await DB.profile()}catch(e){}S.user=p;if(p&&p.country&&!S.countryTouched){S.country=p.country}if(unsub){unsub();unsub=null}
if(p){unsub=DB.subscribe(p.id,()=>{refreshBadge();const r=location.hash.replace(/^#\/?/,'').split('/')[0];if(['messages','chat'].includes(r)&&!tmp.busy&&!(document.activeElement&&document.activeElement.id==='cm'&&$('#cm').value))rerender(true)},()=>{refreshBadge();rerender(true)})}
await refreshBadge()}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&S.user){refreshBadge();const r=location.hash.replace(/^#\/?/,'').split('/')[0];if(['messages','chat'].includes(r))rerender(true)}});
window.addEventListener('hashchange',route);
(async()=>{DB.onAuth((ev)=>{if(ev==='PASSWORD_RECOVERY')location.hash='#/reset';if(ev==='SIGNED_OUT'&&S.user){loadUser().then(()=>rerender())}});await loadUser();await route()})();
